  'Language for navigation, settings labels, and common controls. Other copy falls back to English. Speech recognition keeps its own language.':
    'Мова навігації, назв налаштувань і основних елементів керування. Інший текст відображатиметься англійською. Для розпізнавання мовлення використовується окрема мова.',
