  'Battery & background activity': 'Акумулятор і фонова активність',
  'The open computer updates live. Less frequent checks of other computers reduce network activity. Connections pause while the app is in the background; notifications and Live Activities are managed in Notifications. Disabled widgets keep their last saved snapshot.':
    'Відкритий комп’ютер оновлюється наживо. Менш часті перевірки інших комп’ютерів зменшують мережеву активність. Підключення призупиняються, коли застосунок працює у фоновому режимі; сповіщення й Live Activities налаштовуються в розділі «Сповіщення». Вимкнені віджети зберігають останній знімок.',
