  Confirmations: 'Підтвердження',
  'Archived threads can always be restored from Settings → Archived threads. Stopping pauses queued messages.':
    'Архівовані обговорення завжди можна відновити в розділі «Налаштування» → «Архівовані обговорення». Зупинення призупиняє повідомлення в черзі.',
  'Confirm before archiving a task': 'Підтверджувати архівацію завдання',
