  'Turn off Minimal composer to always show the full composer. Tool activity controls whether commands, edits and searches start open or folded. Tool call details show output and full inputs only when enabled. The screen stays on only while you have a running task open.':
    'Вимкніть мінімальне поле введення, щоб завжди показувати повне. Налаштування «Активність інструментів» визначає, чи команди, редагування та пошукові запити спочатку розгорнуті чи згорнуті. Докладні відомості про виклики інструментів показують вивід і повні вхідні дані, лише якщо цю функцію ввімкнено. Екран не вимикатиметься, лише поки відкрите поточне завдання.',
