    'Ця гілка залишиться лише для читання. Повторіть спробу перенесення або скасуйте його. Скасування розблокує гілку лише після підтвердження від {value0}, що копію видалено. Якщо {value1} уже отримав гілку, скасування натомість завершує перенесення.',
