  '{value0} symbolic links skipped.': 'Пропущено символічних посилань: {value0}.',
  'Cancel move': 'Скасувати перенесення',
  'Cancel copy': 'Скасувати копіювання',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Перенесіть усю збережену розмову, контрольний список, вкладення та файли. Сеанси постачальника й облікові дані залишаться тут. У гілці призначення використовуватиметься стандартне середовище виконання цього комп’ютера з доступом не ширшим, ніж у цієї гілки. Нічого не запускається, доки ви не надішлете наступне повідомлення там. Після відкриття можна змінити модель. Ця гілка залишиться тут лише для читання для відновлення.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Скопіюйте файли та локальну історію Git. Вихідний проєкт і чати залишаться тут. На комп’ютері призначення буде створено нову папку. Для робочих дерев використовується налаштована для них папка.',
