  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Налаштуйте CuaDriver на хості цього середовища виконання. CuaDriver керує дозволами ОС; Dovo підключає агентів через MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Назви або шляхи виконуваних файлів на хості без лапок оболонки. Перевизначення для агентів мають перевагу. Нові термінали використовують ці налаштування оболонки.',
  'Loading {value0} settings…': 'Завантаження налаштувань {value0}…',
  'computer-use': 'використання комп’ютера',
  command: 'команда',
  'Shell arguments (one per line)': 'Аргументи оболонки (по одному на рядок)',
