  'Enable agent computer use on this computer':
    'Увімкнути використання комп’ютера агентом на цьому комп’ютері',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Надає агентам із правом запису доступ до робочого столу цього комп’ютера. Агенти лише для читання не мають доступу. Користувачі й агенти спільно використовують робочий стіл і стан застосунків.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Залиште поле Cua Driver порожнім, щоб знайти його в PATH цього комп’ютера або стандартній теці встановлення. Зміни застосовуються до нових ходів агента.',
  '1. Install on this computer': '1. Установлення на цьому комп’ютері',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Запустіть офіційний інсталятор на хості середовища виконання, а потім оновіть стан. Інсталятор завантажить і встановить CuaDriver; обліковий запис Cua не потрібен.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Для мінімальних систем Linux потрібні libxi6 і at-spi2-core. GNOME потрібен допоміжний компонент WinRects із комплекту Cua; див. посібник зі встановлення.',
  'Install and set up Cua Driver': 'Установити й налаштувати Cua Driver',
  'Detect / check Cua Driver': 'Виявити / перевірити Cua Driver',
  '2. Permissions & desktop access': '2. Дозволи й доступ до робочого столу',
  '3. Agent MCP, skills & hooks': '3. MCP, навички та хуки агента',
  '4. Computer History (optional preview)':
    '4. Історія комп’ютера (необов’язковий попередній перегляд)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Надайте CuaDriver дозволи «Універсальний доступ» і «Запис екрана» в macOS та погодьтеся на перезапуск. Перевірка доступу до робочого столу показує список програм, не змінюючи їх. Керування демоном впливає на активні сеанси використання комп’ютера.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Збережіть перемикач використання комп’ютера, щоб автоматично вмикати MCP dovo_cua для нових ходів із правом запису. Реєструвати MCP вручну не потрібно. Установіть офіційний додатковий набір навичок; під час встановлення буде пов’язано виявлених агентів на цьому комп’ютері.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Історія з метаданими без вмісту, з шифруванням і лише за згодою. Увімкнення може перезапустити демон. Вимкнення зберігає записані дані; пауза тимчасово припиняє запис. Непідтримувані версії повідомляють про помилку. Дані залишаються на хості середовища виконання; команда «Переглянути останні події» отримує сюди до 20 подій.',
  'Delete recorded Computer History?': 'Видалити записану історію комп’ютера?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Видалити всю записану історію та її ключ шифрування на цьому комп’ютері. Цю дію не можна скасувати.',
