  'Computer defaults apply when scoped Task lifecycle settings inherit. Scoped restart and archiving rules take precedence.':
    'Типові налаштування комп’ютера застосовуються, якщо для області дії завдання вибрано успадкування життєвого циклу. Правила перезапуску й архівування для області дії мають перевагу.',
  'Open scoped task lifecycle': 'Відкрити налаштування життєвого циклу для області дії',
  'Saved on this computer and shared with its paired devices. Switches and choices save automatically.':
    'Збережено на цьому комп’ютері й поширено на сполучені пристрої. Перемикачі й варіанти зберігаються автоматично.',
  'This computer is offline. Reconnect to load and change its preferences.':
    'Цей комп’ютер офлайн. Підключіться знову, щоб завантажити й змінити його налаштування.',
  'Loading computer preferences…': 'Завантаження налаштувань комп’ютера…',
  'Retry computer preferences': 'Повторити завантаження налаштувань комп’ютера',
