  'Use custom TURN': 'Використовувати власний TURN',
  'Use automatic relay': 'Використовувати автоматичний ретранслятор',
  'Relay fallback': 'Резервний ретранслятор',
  'The computer must allow relay in its pairing QR. For a Direct-only pairing, generate a new Dovo-enabled QR on the computer and pair again.':
    'Комп’ютер має дозволяти ретрансляцію у своєму QR-коді сполучення. Якщо сполучення налаштовано лише для прямого з’єднання, створіть на комп’ютері новий QR-код із підтримкою Dovo й виконайте сполучення знову.',
  'Scan pairing QR code': 'Сканувати QR-код сполучення',
  'Point your camera at the QR code shown by Dovo Studio or the server’s pair command.':
    'Наведіть камеру на QR-код, показаний у Dovo Studio або командою сполучення сервера.',
  'Allow camera access to scan a pairing code. You can also enter the address and code manually.':
    'Дозвольте доступ до камери, щоб сканувати код сполучення. Також можна вручну ввести адресу й код.',
  'Allow camera': 'Дозволити доступ до камери',
  'Open Settings': 'Відкрити Налаштування',
  'Try another code': 'Спробувати інший код',
  'Enter address and code manually': 'Ввести адресу й код вручну',
  'Enter the new address and a fresh pairing code from the same computer. Your saved connection stays unchanged until pairing succeeds.':
    'Введіть нову адресу й актуальний код сполучення з того самого комп’ютера. Збережене підключення залишиться без змін, доки сполучення не буде успішно завершено.',
  'On your computer, open Dovo and choose {value0} in Settings → Devices & runtime.':
    'На комп’ютері відкрийте Dovo й виберіть {value0} у меню Налаштування → Пристрої та середовище виконання.',
  'Connect your phone': 'Під’єднати телефон',
  'Scan the QR code in this app to connect over the internet. No VPN or local IP needed. You can also pair using a LAN / VPN address.':
    'Відскануйте QR-код у цій програмі, щоб під’єднатися через інтернет. VPN або локальна IP-адреса не потрібні. Також можна виконати сполучення через адресу LAN / VPN.',
  'Internet connection': 'Підключення до інтернету',
  'WebRTC + STUN · end-to-end encrypted. No VPN or computer address needed. Keep Dovo open on the computer.':
    'WebRTC + STUN · наскрізне шифрування. VPN або адреса комп’ютера не потрібні. Не закривайте Dovo на комп’ютері.',
