    'Повторно підключається. Торкніться й утримуйте, щоб переглянути подробиці',
  'This phone is no longer paired with a computer below. It was removed on that computer, or the runtime was reset. Pair it again from Devices in Settings.':
    'Цей телефон більше не сполучено з комп’ютером нижче. Сполучення видалено на тому комп’ютері або середовище виконання скинуто. Сполучіть пристрої знову в меню «Пристрої» в Налаштуваннях.',
  'Connected using HTTP updates. Live streaming is reconnecting or unavailable. Reconnect to retry it.':
    'Під’єднано через оновлення HTTP. Пряме потокове передавання повторно під’єднується або недоступне. Під’єднайтеся знову, щоб повторити спробу.',
  'Saved work stays available. Reconnect a computer to send messages or run commands there.':
    'Збережена робота доступна. Під’єднайте комп’ютер, щоб надсилати йому повідомлення або виконувати на ньому команди.',
