  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Сполучити знову',
  'Connection stages': 'Етапи підключення',
  'Start your computer': 'Запустіть комп’ютер',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Відкрийте Dovo на комп’ютері й не переводьте його в режим сну. У меню Налаштування → Пристрої та середовище виконання ввійдіть в обліковий запис і ввімкніть Dovo Connect. Увійдіть у той самий обліковий запис на телефоні й виберіть Connect. Для доступу через інтернет не потрібні код сполучення, VPN або локальна IP-адреса.',
  'Direct internet connection': 'Пряме підключення через інтернет',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN з’єднує телефон безпосередньо з комп’ютером. Вміст захищено наскрізним шифруванням. Якщо мережа блокує прямі підключення, увімкнення Dovo Connect дає змогу використовувати зашифрований ретранслятор. Він пересилає зашифрований трафік і не може прочитати ваш вміст.',
  'LAN / VPN connections': 'Підключення через LAN / VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Виконайте окреме сполучення через LAN / VPN, щоб за можливості віддавати перевагу цьому підключенню. Скопіюйте повну адресу Wi-Fi, Tailscale, NetBird або HTTPS, показану на комп’ютері, разом із портом. Адреси localhost і 0.0.0.0 недоступні для телефона.',
  'Check your network': 'Перевірте мережу',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Під’єднайте обидва пристрої до тієї самої мережі Wi-Fi або до VPN. Для підключення через Wi-Fi дозвольте Dovo доступ до локальної мережі в Налаштуваннях iPhone.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Термін дії кодів сполучення — дві хвилини. Коди CLI підтверджуються автоматично; код із комп’ютерної версії може потребувати підтвердження на комп’ютері.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Сполучення збережено. Перш ніж створювати інший код, спробуйте під’єднатися знову. Якщо адресу змінено, виберіть «Оновити адресу підключення» в налаштуваннях цього комп’ютера.',
